<?php $m=$movement; ?>
<section class="page-heading inventory-heading"><div><h1><?= e(App\Services\StockService::label($m)) ?> #<?= (int)$m['id'] ?></h1><p><?= e($m['name'].' · '.$m['sku']) ?></p></div><div class="product-actions"><a class="button" href="<?= e(url('/inventory/movements')) ?>&amp;product_id=<?= (int)$m['product_id'] ?>">Product history</a><?php if(can(current_user(),'inventory.adjust') && !$m['reversed_by'] && $m['movement_type']!=='reversal'): ?><a class="button" href="<?= e(url('/inventory/form')) ?>&amp;kind=reverse&amp;movement_id=<?= (int)$m['id'] ?>">Reverse entry</a><?php endif; ?></div></section>
<?php if($notice): ?><div class="notice" role="status"><?= e($notice) ?></div><?php endif; ?>
<div class="info-strip">This posted movement cannot be edited or deleted. Reversals create a separate linked audit entry.</div>
<section class="surface product-section"><dl class="product-facts"><dt>Product</dt><dd><?php if(can(current_user(),'products.manage')): ?><a href="<?= e(url('/products/view')) ?>&amp;id=<?= (int)$m['product_id'] ?>"><?= e($m['name']) ?></a><?php else: ?><?= e($m['name']) ?><?php endif; ?></dd><dt>SKU</dt><dd><?= e($m['sku']) ?></dd><dt>Posted timestamp</dt><dd><?= e(local_datetime($m['created_at'])) ?></dd><dt>Entry date</dt><dd><?= e($m['entry_date']??substr($m['created_at'],0,10)) ?></dd><dt>Previous stock</dt><dd><?= quantity($m['previous_stock']) ?></dd><dt>Quantity change</dt><dd><?= $m['quantity_delta']>0?'+':'' ?><?= quantity($m['quantity_delta']) ?></dd><dt>Resulting stock</dt><dd><?= quantity($m['resulting_stock']) ?></dd><dt>Cost per item</dt><dd><?= money($m['unit_cost']) ?> <small><?= $m['cost_provided'] || $m['movement_type']==='opening'?'Recorded purchase cost':'Carrying / average cost basis' ?></small></dd><dt>Reason</dt><dd><?= e($m['reason']??'Not recorded on legacy entry') ?></dd><dt>Reference</dt><dd><?= e($m['reference_id']??'—') ?></dd><dt>Notes</dt><dd><?= e($m['note']??'—') ?></dd><dt>Performed by</dt><dd><?= e($m['actor_name']) ?></dd><?php if($m['reverses_movement_id']): ?><dt>Reverses movement</dt><dd><a href="<?= e(url('/inventory/movement')) ?>&amp;id=<?= (int)$m['reverses_movement_id'] ?>">#<?= (int)$m['reverses_movement_id'] ?></a></dd><?php endif; ?><?php if($m['reversed_by']): ?><dt>Reversed by</dt><dd><a href="<?= e(url('/inventory/movement')) ?>&amp;id=<?= (int)$m['reversed_by'] ?>">#<?= (int)$m['reversed_by'] ?></a></dd><?php endif; ?></dl></section>
<?php if($m['previous_quantity']===null): ?><p class="subtle-text">Legacy entry: previous and resulting quantities are derived from the immutable ledger in posting-ID order. The original record was not rewritten.</p><?php endif; ?>
